WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_ct_resource'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '资源限制', 'kp-eng-ct-resource', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "资源限制型工程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总资金、总耗材有限。不仅要算天数，还要算成本。通常结合最值思想。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "加入了财务要素：“甲队每天费用 5000 元，乙队每天 4000 元。总预算只有 10 万元，问如何安排时间最快完工？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则（性价比优先）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "资源限制下求最优解，核心是比较“性价比”。也就是每一块钱能买到多少工程量。"}]}, {"type": "katexBlock", "attrs": {"content": "性价比 = \\frac{每日效率 P}{每日费用 C}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出甲和乙的效率 P 和费用 C] --> B[算出两队的性价比 P/C]\nB --> C[优先把工作量分配给性价比高的一队]\nC --> D{是否有总工期限制?}\nD -- 无限制 --> E[全让性价比高的队干, 甚至不让另一队上场]\nD -- 有限制(不能超时) --> F[列出时间方程和预算不等式, 寻找边界解]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲队每天完成 1/10，费用 2 万元；乙队每天完成 1/15，费用 1 万元。预算不超过 16 万元，怎么安排两队合作总天数最少？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看性价比：甲 2 万买 1/10 (性价比1/20)；乙 1 万买 1/15 (性价比1/15)。乙更便宜划算。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看效率：甲每天干 1/10，乙每天干 1/15。要想“总天数最少”，就必须让效率高的甲尽可能多干！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "建立博弈：既要省钱(多用乙)，又要快(多用甲)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列方程找边界：设甲干 x 天，乙干 y 天。1) 2x + 1y ≤ 16；2) x/10 + y/15 ≥ 1。要求 x 和 y 组合使得时间最小。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "实战秒杀：考场上直接拿着选项中的天数组合代入这两个不等式，满足预算且完工的就是答案。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一味追求省钱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目问的是“天数最少”（求快），而不是“最省钱”。所以必须在预算的红线边缘疯狂试探，把预算全部花光在甲队（快队）身上才是正解。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "资源限制题本质是统筹规划。不要在考场上解线性规划方程，直接代入选项验证“总钱数是否超标”和“总量是否干完”即可。"}]}]}$$ AS jsonb), NULL, '资源限制的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "资源限制"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_ct_resource", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
